<?php
declare(strict_types=1);
session_start(['cookie_httponly'=>true,'cookie_samesite'=>'Strict','cookie_secure'=>!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS']!=='off']);
header('Cache-Control: no-store');
header('X-Content-Type-Options: nosniff');
$private=dirname(__DIR__).'/adlisho-private';
$done=is_file($private.'/installed.lock');
if(empty($_SESSION['setup_csrf'])) $_SESSION['setup_csrf']=bin2hex(random_bytes(32));
$error='';
if($_SERVER['REQUEST_METHOD']==='POST' && !$done){
 try {
  if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['setup_csrf'],$_POST['csrf'])) throw new Exception('صفحه را تازه کنید.');
  if(PHP_VERSION_ID<70400) throw new Exception('PHP نسخه ۷.۴ یا بالاتر لازم است.');
  $files=json_decode(base64_decode(''),true,512,JSON_THROW_ON_ERROR);
  foreach($files as $name=>$data) if(file_exists(__DIR__.'/'.$name)) throw new Exception('مسیر خالی نیست؛ برای حفظ فایل‌ها نصب متوقف شد: '.$name);
  if(!is_dir($private) && !mkdir($private,0700)) throw new Exception('ساخت پوشه خصوصی خارج از public_html ممکن نیست.');
  $mutex=fopen($private.'/setup.lock','c');
  if(!$mutex||!flock($mutex,LOCK_EX|LOCK_NB)) throw new Exception('نصب دیگری در حال اجرا است.');
  if(is_file($private.'/installed.lock')) throw new Exception('نصب قبلاً انجام شده است.');
  if(is_file($private.'/config.php')) throw new Exception('تنظیمات قبلی موجود است؛ نصب متوقف شد.');
  $created=[];
  try {
   $config=['RELAY_URL'=>'','RELAY_SECRET'=>bin2hex(random_bytes(32))];
   $handle=fopen($private.'/config.php','x');
   if(!$handle) throw new Exception('ذخیره تنظیمات ممکن نیست.');
   $created[]=$private.'/config.php';
   $data="<?php\nreturn ".var_export($config,true).";\n";
   if(fwrite($handle,$data)!==strlen($data)) throw new Exception('نوشتن تنظیمات ناموفق بود.');
   fclose($handle);chmod($private.'/config.php',0600);
   foreach($files as $name=>$encoded){
    $path=__DIR__.'/'.$name; $data=base64_decode($encoded,true);$handle=fopen($path,'x');
    if(!$handle) throw new Exception('ساخت فایل ممکن نیست: '.$name);
    $created[]=$path;
    if(fwrite($handle,$data)!==strlen($data)) throw new Exception('فضای هاست کافی نیست.');
    fclose($handle);chmod($path,0644);
   }
   if(file_put_contents($private.'/installed.lock',gmdate('c'),LOCK_EX)===false) throw new Exception('ثبت پایان نصب ناموفق بود.');
   $done=true;
  }catch(Throwable $e){foreach(array_reverse($created) as $path) @unlink($path);throw $e;}
  flock($mutex,LOCK_UN);fclose($mutex);
 }catch(Throwable $e){$error=$e->getMessage();}
}
?><!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>نصب عدلی‌شو</title><style>body{margin:0;background:#071b27;color:#edfaff;min-height:100vh;display:grid;place-items:center;font:17px/2 Tahoma,sans-serif}main{max-width:520px;margin:25px;padding:36px;border:1px solid #32505b;border-radius:28px;background:#102c3b}h1{font-size:30px}button,a{display:block;background:#92efd0;color:#08271e;border:0;border-radius:15px;padding:16px;text-align:center;font:inherit;text-decoration:none;cursor:pointer;width:100%;box-sizing:border-box}.error{color:#ffbaba}small{color:#adbec8}</style><main><small>ADLISHO.ONLINE · نصب تازه</small><h1><?= $done?'سایت آماده است':'با یک کلیک راه‌اندازی کن' ?></h1><?php if($done): ?><p>سایت نصب شد و ثبت کلیک محلی فعال است. ارسال تلگرام هنوز تنظیم نشده است.</p><a href="./">ورود به سایت</a><p><small>فایل adlisho-install.php را از File Manager حذف کنید.</small></p><?php else: ?><p>فایل‌های سایت در همین مسیر نصب می‌شوند. بانک اطلاعاتی لازم نیست و سکرت اختصاصی خودکار ساخته می‌شود.</p><p class="error"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></p><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['setup_csrf'],ENT_QUOTES,'UTF-8')?>"><button>نصب سایت</button></form><small>این فایل را در public_html دامنهٔ adlisho.online قرار دهید. مسیر باید خالی باشد.</small><?php endif; ?></main></html>